<?php
require_once __DIR__.'/../config/app.php';require_admin();$status=$_GET['status']??'';$payment=$_GET['payment']??'';$q=trim($_GET['q']??'');$where=['1=1'];$params=[];if(in_array($status,['pending','processing','packed','shipped','completed','cancelled'],true)){$where[]='o.order_status=?';$params[]=$status;}if(in_array($payment,['unpaid','waiting_verification','paid','rejected','refunded'],true)){$where[]='o.payment_status=?';$params[]=$payment;}if($q!==''){$where[]='(o.order_number LIKE ? OR u.name LIKE ? OR u.email LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}$stmt=db()->prepare('SELECT o.*,u.name,u.email FROM orders o JOIN users u ON u.id=o.user_id WHERE '.implode(' AND ',$where).' ORDER BY o.created_at DESC');$stmt->execute($params);$orders=$stmt->fetchAll();$pageTitle='Pesanan';require APP_ROOT.'/includes/admin-header.php';
?>
<div class="admin-card mb-4"><div class="admin-card-body"><form class="row g-2"><div class="col-lg-5"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Cari nomor pesanan, nama, atau email"></div><div class="col-lg-2"><select class="form-select" name="status"><option value="">Semua status</option><?php foreach(['pending','processing','packed','shipped','completed','cancelled'] as $s):?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= order_status_label($s) ?></option><?php endforeach;?></select></div><div class="col-lg-3"><select class="form-select" name="payment"><option value="">Semua pembayaran</option><?php foreach(['unpaid','waiting_verification','paid','rejected','refunded'] as $s):?><option value="<?= $s ?>" <?= $payment===$s?'selected':'' ?>><?= payment_status_label($s) ?></option><?php endforeach;?></select></div><div class="col-lg-2 d-grid"><button class="btn btn-primary">Filter</button></div></form></div></div><div class="admin-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Pesanan</th><th>Pembeli</th><th>Total</th><th>Pembayaran</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="6" class="text-center text-muted py-5">Tidak ada pesanan.</td></tr><?php endif;foreach($orders as $order):?><tr><td><strong><?= e($order['order_number']) ?></strong><div class="small text-muted"><?= date('d M Y H:i',strtotime($order['created_at'])) ?></div></td><td><?= e($order['name']) ?><div class="small text-muted"><?= e($order['email']) ?></div></td><td><strong><?= rupiah($order['total_amount']) ?></strong><div class="small text-muted"><?= $order['fulfillment_method']==='pickup'?'COD DI TOKO':strtoupper($order['payment_method']) . ' ANTAR' ?></div></td><td><span class="badge text-bg-<?= status_class($order['payment_status']) ?>"><?= payment_status_label($order['payment_status']) ?></span></td><td><span class="badge text-bg-<?= status_class($order['order_status']) ?>"><?= order_status_label($order['order_status']) ?></span></td><td class="text-end"><a class="btn btn-sm btn-primary" href="<?= url('admin/order-detail.php?id='.$order['id']) ?>">Detail</a></td></tr><?php endforeach;?></tbody></table></div></div>
